class Solution {int n;vector<int>a;vector<vector<int>>memo;int dfs(int mask,int last){if(mask==(1<<n)-1)return abs(last-a[0]);int&v=memo[mask][last];if(v!=-1)return v;v=INT_MAX/4;for(int j=1;j<n;++j)if(!(mask>>j&1))v=min(v,abs(last-a[j])+dfs(mask|1<<j,j));return v;}
 public:vector<int> findPermutation(vector<int>& nums){a=nums;n=a.size();memo.assign(1<<n,vector<int>(n,-1));vector<int>ans={0};int mask=1,last=0;while(mask!=(1<<n)-1){int best=dfs(mask,last);for(int j=1;j<n;++j)if(!(mask>>j&1)&&abs(last-a[j])+dfs(mask|1<<j,j)==best){ans.push_back(j);mask|=1<<j;last=j;break;}}return ans;}
};
